// loads the vendored radar snapshots with their provenance. snapshots
// are generated by scripts/import-snapshots.mjs from the radar
// branches and committed here, so the engine's evidence is always
// inspectable and always dated.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

export interface RadarRow {
  [key: string]: unknown;
  verified_on?: string | null;
  recheck_cadence_days?: number;
}

export interface RadarSnapshot {
  radar: string;
  schema_version: string;
  commit: string;
  exported_at: string;
  rows: RadarRow[];
  registrars?: RadarRow[];
}

function load(name: string): RadarSnapshot {
  const here = dirname(fileURLToPath(import.meta.url));
  const raw = readFileSync(join(here, "..", "snapshots", name + ".json"), "utf8");
  return JSON.parse(raw) as RadarSnapshot;
}

export const SNAPSHOTS = {
  theproviderradar: load("theproviderradar"),
  thevoipradar: load("thevoipradar"),
  thetldradar: load("thetldradar"),
  theccradar: load("theccradar"),
} as const;
